INSERT INTO `Game_component_library` (`id`, `type`, `name`, `description`, `action_type`, `range`, `attribute`, `attack_type`, `damage_type`, `magic_effect`, `projectile`, `uses`, `uses_spent`, `duration`, `precondition`, `components`, `material`) VALUES (1,'talent','Stangenwaffenmeister','Wenn du die Angriffsaktion wählst und nur mit einer Glefe, Hellebarde oder einem Kampfstab angreifst, kannst du deine Bonusaktion aufwenden, um einen weiteren Angriff mit dem anderen Ende der Waffe auszuführen. Dieser Angriff verwendet denselben Attributsmodifikator wie der erste und verursacht 1W4 Wuchtschaden. \r\nSolange du eine Glefe, Hellebarde, Pike oder einen Kampfstab führst, provozieren andere Kreaturen einen Gelegenheitsangriff durch dich, wenn sie sich in Reichweite der Waffe begeben.												\r\n','Bonus','','','','','','',0,0,'','','','');
INSERT INTO `Game_component_library_translation` (`component_id`, `lang`, `name`, `description`, `action_type`, `range`, `attack_type`, `magic_effect`, `projectile`, `duration`, `precondition`, `components`, `material`) VALUES (1,'de','Stangenwaffenmeister','Wenn du die Angriffsaktion wählst und nur mit einer Glefe, Hellebarde oder einem Kampfstab angreifst, kannst du deine Bonusaktion aufwenden, um einen weiteren Angriff mit dem anderen Ende der Waffe auszuführen. Dieser Angriff verwendet denselben Attributsmodifikator wie der erste und verursacht 1W4 Wuchtschaden.\nSolange du eine Glefe, Hellebarde, Pike oder einen Kampfstab führst, provozieren andere Kreaturen einen Gelegenheitsangriff durch dich, wenn sie sich in Reichweite der Waffe begeben.','Bonusaktion',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO `Game_component_library_translation` (`component_id`, `lang`, `name`, `description`, `action_type`, `range`, `attack_type`, `magic_effect`, `projectile`, `duration`, `precondition`, `components`, `material`) VALUES (1,'en','Polearm Master','When you take the Attack action and attack only with a glaive, halberd or quarterstaff, you can use your bonus action to make one more attack with the other end of the weapon. This attack uses the same ability modifier as the first attack and deals 1d4 bludgeoning damage.\nWhile you wield a glaive, halberd, pike or quarterstaff, other creatures provoke an opportunity attack from you when they enter the reach of the weapon.','Bonus action',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
